import sys
from collections import defaultdict

def main():
    n, m = map(int, sys.stdin.readline().split())
    adj = defaultdict(set)
    for _ in range(m):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].add(b)

    count = 0
    for a in range(1, n+1):
        for b in adj[a]:
            for c in adj[b]:
                if c == a:
                    continue
                for d in adj[a]:
                    if d == b or d == c:
                        continue
                    if c in adj[d]:
                        count += 1
